mapper.select:
select proposal_id, config_json from ontology_proposal
where task_id = #{taskId} and proposal_id = #{proposalId}
limit 1

select config_json from ontology_proposal
where task_id = #{taskId} and proposal_id = #{proposalId}
limit 1

mapper.update:
update ontology_proposal
set config_json = #{configJson}, update_by = #{username}, update_time = now()
where proposal_id = #{proposalId}

update analysis_task
set summary = #{summary}, update_by = #{username}, update_time = now()
where task_id = #{taskId}

mapper.select:
select 
from ontology_analysis_memory
where status = #{status} and memory_type = #{memoryType}
  and (task_id = #{taskId} or space_id = #{spaceId})
order by update_time desc, memory_id desc
limit #{limit}

select 
from ontology_analysis_memory
where status = #{status} and memory_type = #{memoryType} and task_id = #{taskId}
order by update_time desc, memory_id desc
limit #{limit}

select 
from ontology_analysis_memory
where status = #{status} and memory_type = #{memoryType} and space_id = #{spaceId}
order by update_time desc, memory_id desc
limit #{limit}

select api_base_url, api_key_enc, model, provider_type
from ontology_llm_settings
where enabled = #{enabled}
